-- Flow's published scale signal is Chile-specific; preserve the correction in-place.
update public.aml_fintech_market_metric_observation
set geography='CHILE',
    basis=coalesce(basis,'') || ' [Corrección: la fuente citada corresponde al sitio chileno de Flow y no respalda una cifra LATAM.]',
    metadata=coalesce(metadata,'{}'::jsonb) || jsonb_build_object('geography_corrected_2026_09_09',true,'previous_geography','LATAM'),
    observed_at=now(),last_seen_at=now()
where observation_key='COMPANY_OFFICIAL|FLOW|TRANSACTIONS_MONTHLY_COUNT|2026-09-09';

